1	// Package chainledger implements the on-chain data governance core.
2	package chainledger
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"sort"
8		"unicode/utf8"
9	)
10	
11	// PlanChange is one record in a lineage adjustment plan: the dataset name and
12	// the complete list of its direct upstreams after the batch is applied.
13	//
14	// A change may name a dataset that does not exist yet (it is registered) or an
15	// existing dataset (its direct upstreams are replaced wholesale). Datasets not
16	// mentioned in the plan keep their current direct upstreams.
17	type PlanChange struct {
18		Name      string   `json:"name"`
19		Upstreams []string `json:"upstreams"`
20	}
21	
22	// Plan is a batch of lineage adjustments read from a JSON file.
23	//
24	// Removals names datasets that must be absent from the final graph. Deleting a
25	// name that does not currently exist is a no-op (it is not reported as an
26	// actual removal), so a successful plan can be applied again with empty change
27	// and impact lists. A name listed in Removals must not also appear in Changes.
28	type Plan struct {
29		Changes  []PlanChange `json:"changes"`
30		Removals []string     `json:"removals"`
31	}
32	
33	// Relation is a directed lineage edge: Upstream -> Downstream, meaning the
34	// downstream dataset derives from the upstream dataset.
35	type Relation struct {
36		Upstream   string `json:"upstream"`
37		Downstream string `json:"downstream"`
38	}
39	
40	// GraphDataset is one dataset record in the on-disk graph JSON.
41	type GraphDataset struct {
42		Name      string   `json:"name"`
43		Upstreams []string `json:"upstreams"`
44	}
45	
46	// GraphFile is the on-disk JSON representation of a lineage graph.
47	type GraphFile struct {
48		Datasets []GraphDataset `json:"datasets"`
49	}
50	
51	// BatchReport is the deterministic report produced by preview and apply.
52	//
53	// All slices are non-nil (empty lists encode as [] in JSON). Datasets and name
54	// lists are sorted by name byte order; relation lists are sorted by upstream
55	// then downstream.
56	type BatchReport struct {
57		FinalGraph          GraphFile  `json:"finalGraph"`
58		NewDatasets         []string   `json:"newDatasets"`
59		ChangedDatasets     []string   `json:"changedDatasets"`
60		RemovedDatasets     []string   `json:"removedDatasets"`
61		AddedRelations      []Relation `json:"addedRelations"`
62		RemovedRelations    []Relation `json:"removedRelations"`
63		AffectedDownstreams []string   `json:"affectedDownstreams"`
64	}
65	
66	// graphAdjacency derives the normalized parent map from the in-memory graph.
67	// It rejects nil lineage nodes, empty names, names that are not valid UTF-8
68	// (dataset names or direct upstream references), and references to upstreams
69	// that are not registered; the name/reference rules are the shared ones from
70	// normalizeDatasets and validateAdjacencyReferences, also used by the file and
71	// snapshot readers. It does not check for cycles; use validateAcyclic for that.
72	func graphAdjacency(graph map[string]*Lineage) (adjacency, error) {
73		if graph == nil {
74			return nil, fmt.Errorf("%w: create the graph map with make before validating", ErrNotInitialized)
75		}
76		// Check encoding before anything that would quote these names or turn them
77		// into JSON: a missing-upstream check must not label an unregistered,
78		// non-UTF-8 upstream as ErrNotFound when the name itself is unusable, and
79		// json.Marshal would silently rewrite an invalid byte into U+FFFD. The
80		// check is read-only and reports the offending raw bytes.
81		if err := validateInMemoryNamesUTF8(graph); err != nil {
82			return nil, err
83		}
84		records := make([]GraphDataset, 0, len(graph))
85		for name, entry := range graph {
86			if entry == nil {
87				return nil, fmt.Errorf("%w: dataset %q points to a nil lineage node", ErrInvalidArgument, name)
88			}
89			if name == "" {
90				return nil, fmt.Errorf("%w: dataset name is required", ErrInvalidArgument)
91			}
92			records = append(records, GraphDataset{Name: name, Upstreams: entry.Parents})
93		}
94		adj, err := normalizeDatasets(records)
95		if err != nil {
96			return nil, err
97		}
98		if err := validateAdjacencyReferences(adj); err != nil {
99			return nil, err
100		}
101		return adj, nil
102	}
103	
104	// ValidateGraph checks the in-memory graph for structural problems: nil nodes,
105	// empty names, names that are not valid UTF-8 (dataset names or direct upstream
106	// references), missing upstreams, and cycles. It does not mutate the graph.
107	//
108	// A graph that fails validation cannot be used as the basis for a batch: an
109	// adjustment plan must not be allowed to paper over pre-existing corruption.
110	func ValidateGraph(graph map[string]*Lineage) error {
111		adj, err := graphAdjacency(graph)
112		if err != nil {
113			return err
114		}
115		return validateAcyclic(adj)
116	}
117	
118	// validatePlanNamesUTF8 rejects a plan in which any name that takes part in
119	// the adjustment — a change record's name, one of its direct upstream names,
120	// or a removals entry — is not valid UTF-8. It is the in-memory counterpart
121	// of the raw-literal scan the plan reader runs (checkPlanNameEncoding): a
122	// Plan built directly in Go never passed through that reader, so without
123	// this gate PreviewBatch and ApplyBatch could register datasets the graph
124	// exporter must refuse and produce reports whose JSON silently rewrites the
125	// bad bytes to U+FFFD (two distinct corrupted names would then print as one).
126	//
127	// Plan order is checked as given: the name of record i comes before its
128	// upstreams, and removals follow all changes, so the first reported position
129	// is the earliest offending name the caller submitted. The error names the
130	// field ("name", "upstreams", or "removals"), the zero-based record or array
131	// position, and — for an upstream — its zero-based position inside that
132	// record. The offending name is quoted with %q, which renders the original
133	// bytes as \x escapes rather than replacing them with U+FFFD, so "p\xff" and
134	// "p\xfe" stay distinguishable. The plan is only read, never normalized or
135	// mutated. Register keeps accepting raw Go strings; this gate belongs only
136	// to the batch boundary, where an unusable name would enter a graph and a
137	// report that are promised exportable.
138	func validatePlanNamesUTF8(plan Plan) error {
139		for i, change := range plan.Changes {
140			if !utf8.ValidString(change.Name) {
141				return fmt.Errorf("%w: field %q in the change record at index %d of %q contains invalid UTF-8 bytes: %q",
142					ErrInvalidArgument, "name", i, "changes", change.Name)
143			}
144			for j, upstream := range change.Upstreams {
145				if !utf8.ValidString(upstream) {
146					// Report the unusable name itself, never a missing-upstream
147					// error: the encoding defect takes precedence over whether
148					// the referenced dataset exists in the final graph.
149					return fmt.Errorf("%w: field %q at index %d in the change record at index %d of %q contains invalid UTF-8 bytes: %q",
150						ErrInvalidArgument, "upstreams", j, i, "changes", upstream)
151				}
152			}
153		}
154		for i, name := range plan.Removals {
155			if !utf8.ValidString(name) {
156				return fmt.Errorf("%w: field %q at index %d contains invalid UTF-8 bytes: %q",
157					ErrInvalidArgument, "removals", i, name)
158			}
159		}
160		return nil
161	}
162	
163	// computeBatch validates the graph and plan, then computes the final adjacency
164	// and the diff report. It does not mutate graph. The returned adjacency is the
165	// graph as it will be after the batch; callers that want to commit it should
166	// pass it to applyAdjacency.
167	func computeBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, adjacency, error) {
168		if err := ValidateGraph(graph); err != nil {
169			return nil, nil, err
170		}
171		original, err := graphAdjacency(graph)
172		if err != nil {
173			return nil, nil, err
174		}
175	
176		// Check every name the plan carries before anything that would quote it,
177		// hash it, or turn the report into JSON: the file reader already rejects
178		// these at the raw-literal level, but a plan constructed directly through
179		// the Go API bypasses that reader, and without this gate it could register
180		// a dataset whose name cannot be exported — two names differing only in an
181		// invalid byte ("p\xff" vs "p\xfe") would even render identically once the
182		// report is marshaled. This is the in-memory counterpart of the raw scan;
183		// see name_encoding.go.
184		if err := validatePlanNamesUTF8(plan); err != nil {
185			return nil, nil, err
186		}
187	
188		// Validate the plan: empty names and duplicate declarations reject the
189		// whole batch, naming the dataset and the reason.
190		declarations := make(map[string]int, len(plan.Changes))
191		for _, change := range plan.Changes {
192			if change.Name == "" {
193				return nil, nil, fmt.Errorf("%w: plan contains a dataset with an empty name", ErrInvalidArgument)
194			}
195			declarations[change.Name]++
196			if declarations[change.Name] > 1 {
197				return nil, nil, fmt.Errorf("%w: dataset %q is declared %d times in the plan", ErrInvalidArgument, change.Name, declarations[change.Name])
198			}
199		}
200	
201		// Validate removals: empty names, duplicate names, and names also declared
202		// as changes all reject the whole batch with the name and reason.
203		removalDecls := make(map[string]int, len(plan.Removals))
204		for _, name := range plan.Removals {
205			if name == "" {
206				return nil, nil, fmt.Errorf("%w: plan removals contain a dataset with an empty name", ErrInvalidArgument)
207			}
208			removalDecls[name]++
209			if removalDecls[name] > 1 {
210				return nil, nil, fmt.Errorf("%w: dataset %q is listed %d times in removals", ErrInvalidArgument, name, removalDecls[name])
211			}
212			if _, ok := declarations[name]; ok {
213				return nil, nil, fmt.Errorf("%w: dataset %q appears in both changes and removals", ErrInvalidArgument, name)
214			}
215		}
216	
217		// Build the final adjacency: start from the original parents, replace each
218		// planned dataset's parents with its normalized upstreams. Being named in
219		// the plan does not by itself make a dataset new or changed — that is
220		// judged below by diffing the original and final graphs, exactly the way a
221		// snapshot comparison judges two versions.
222		final := make(adjacency, len(original)+len(plan.Changes))
223		for name, parents := range original {
224			final[name] = append([]string(nil), parents...)
225		}
226		for name := range removalDecls {
227			delete(final, name)
228		}
229		for _, change := range plan.Changes {
230			final[change.Name] = uniqueSorted(change.Upstreams)
231		}
232	
233		// Every upstream must resolve to a dataset that exists in the FINAL graph
234		// (new datasets may reference each other regardless of plan order; a
235		// retained dataset that still references a deleted name is rejected here,
236		// with both the referrer and the referenced name in the error). Iterate
237		// over sorted names so the reported pair is deterministic.
238		names := make([]string, 0, len(final))
239		for name := range final {
240			names = append(names, name)
241		}
242		sort.Strings(names)
243		for _, name := range names {
244			for _, parent := range final[name] {
245				if _, ok := final[parent]; !ok {
246					return nil, nil, fmt.Errorf("%w: dataset %q references upstream %q which does not exist in the final graph", ErrNotFound, name, parent)
247				}
248			}
249		}
250		// The final graph must be acyclic, judged after all replacements.
251		if err := validateAcyclic(final); err != nil {
252			return nil, nil, err
253		}
254	
255		// Classify the dataset-level changes with the shared old -> new rule a
256		// snapshot comparison uses (see diffDatasets): only-in-final is new,
257		// only-in-original is removed, present-on-both is changed only when the
258		// direct upstream set actually differs. Deleting a name that does not
259		// exist is a no-op and is not reported, so a successful plan can be
260		// applied again with empty change and impact lists.
261		newNames, removedNames, changedNames := diffDatasets(original, final)
262	
263		added, removed := diffRelations(original, final)
264		affected := affectedDownstreams(original, final, newNames, changedNames, removedNames)
265	
266		report := &BatchReport{
267			FinalGraph:          GraphFile{Datasets: adjacencyToDatasets(final)},
268			NewDatasets:         newNames,
269			ChangedDatasets:     changedNames,
270			RemovedDatasets:     removedNames,
271			AddedRelations:      added,
272			RemovedRelations:    removed,
273			AffectedDownstreams: affected,
274		}
275		// Guarantee non-nil slices so JSON encodes empty lists as [].
276		if report.NewDatasets == nil {
277			report.NewDatasets = []string{}
278		}
279		if report.ChangedDatasets == nil {
280			report.ChangedDatasets = []string{}
281		}
282		if report.RemovedDatasets == nil {
283			report.RemovedDatasets = []string{}
284		}
285		if report.AddedRelations == nil {
286			report.AddedRelations = []Relation{}
287		}
288		if report.RemovedRelations == nil {
289			report.RemovedRelations = []Relation{}
290		}
291		if report.AffectedDownstreams == nil {
292			report.AffectedDownstreams = []string{}
293		}
294		return report, final, nil
295	}
296	
297	// PreviewBatch validates the graph and plan and returns the report WITHOUT
298	// mutating graph. Preview and apply for the same graph and plan produce
299	// identical reports.
300	//
301	// As well as the structural plan rules (empty names, duplicate declarations,
302	// unresolvable upstreams, cycles), every name the plan carries — a change
303	// record's name, any of its direct upstreams, and every removals entry — must
304	// be valid UTF-8 even when the plan was constructed directly in Go instead of
305	// read by UnmarshalPlan. A name that is not valid UTF-8 rejects the whole
306	// batch with ErrInvalidArgument before any dataset could be registered or any
307	// report produced, so a success report can always be marshaled to JSON and an
308	// applied graph can always be exported. See validatePlanNamesUTF8.
309	func PreviewBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
310		report, _, err := computeBatch(graph, plan)
311		return report, err
312	}
313	
314	// ApplyBatch validates the plan, applies it to graph, and returns the report.
315	// On rejection — including a plan that names a dataset, upstream, or removal
316	// with bytes that are not valid UTF-8 — graph is left completely unchanged.
317	func ApplyBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
318		report, final, err := computeBatch(graph, plan)
319		if err != nil {
320			return nil, err
321		}
322		applyAdjacency(graph, final)
323		return report, nil
324	}
325	
326	// applyAdjacency rewrites the in-memory graph to match the final adjacency. It
327	// is the apply path of the shared relationship rule in materializeLineage, the
328	// same rule a graph reader follows: nodes absent from final are removed,
329	// parents are replaced wholesale with independent copies, and children are
330	// rebuilt from the parent edges. Surviving *Lineage records are updated in
331	// place, so node pointers a Go caller already holds expose the new
332	// relationships after the batch returns.
333	func applyAdjacency(graph map[string]*Lineage, final adjacency) {
334		materializeLineage(graph, final)
335	}
336	
337	// diffDatasets is the single authority for classifying dataset-level changes
338	// between two versions of a graph, shared by the batch report (preview and
339	// apply) and the snapshot comparison so both can never disagree about the
340	// rule. Changes are always judged in the direction original -> final:
341	//
342	//   - a dataset present only in final is NEW — even when it arrives carrying
343	//     upstreams, it is never also listed as changed;
344	//   - a dataset present only in original is REMOVED — a removed dataset is
345	//     never also listed as an upstream change;
346	//   - a dataset present on both sides is CHANGED only when its direct
347	//     upstream set actually differs; a dataset whose upstreams were cleared
348	//     still exists (as a root), so it is changed, not removed.
349	//
350	// Names are case-sensitive and compared verbatim; only the name set and each
351	// dataset's normalized upstream set matter, never record order, upstream
352	// order, or duplicate upstreams. Each returned list is sorted by name byte
353	// order and is nil when empty; callers normalize nil to [] for JSON.
354	func diffDatasets(original, final adjacency) (newNames, removedNames, changedNames []string) {
355		for name, finalParents := range final {
356			if originalParents, ok := original[name]; !ok {
357				newNames = append(newNames, name)
358			} else if !stringSliceEqual(originalParents, finalParents) {
359				changedNames = append(changedNames, name)
360			}
361		}
362		for name := range original {
363			if _, ok := final[name]; !ok {
364				removedNames = append(removedNames, name)
365			}
366		}
367		sort.Strings(newNames)
368		sort.Strings(removedNames)
369		sort.Strings(changedNames)
370		return newNames, removedNames, changedNames
371	}
372	
373	// diffRelations returns the directed edges present in final but not original
374	// (added) and present in original but not final (removed). Both lists are
375	// sorted by upstream then downstream.
376	func diffRelations(original, final adjacency) (added, removed []Relation) {
377		origEdges := edgeSet(original)
378		finalEdges := edgeSet(final)
379		for e := range finalEdges {
380			if !origEdges[e] {
381				added = append(added, e)
382			}
383		}
384		for e := range origEdges {
385			if !finalEdges[e] {
386				removed = append(removed, e)
387			}
388		}
389		sortRelations(added)
390		sortRelations(removed)
391		return added, removed
392	}
393	
394	// edgeSet collapses the adjacency into a set of upstream->downstream edges.
395	func edgeSet(adj adjacency) map[Relation]bool {
396		set := make(map[Relation]bool)
397		for downstream, parents := range adj {
398			for _, upstream := range parents {
399				set[Relation{Upstream: upstream, Downstream: downstream}] = true
400			}
401		}
402		return set
403	}
404	
405	// sortRelations sorts by upstream then downstream.
406	func sortRelations(rels []Relation) {
407		sort.Slice(rels, func(i, j int) bool {
408			if rels[i].Upstream != rels[j].Upstream {
409				return rels[i].Upstream < rels[j].Upstream
410			}
411			return rels[i].Downstream < rels[j].Downstream
412		})
413	}
414	
415	// affectedDownstreams computes the impact set: starting from the seed datasets
416	// (new, actually changed, or actually removed), follow downstream (children)
417	// edges in BOTH the original and the final graphs. Datasets that are
418	// themselves seeds are excluded from the output; every other reachable dataset
419	// is included once.
420	//
421	// Walking both graphs matters when relations are deleted: a dataset that was
422	// reachable downstream before the change (and thus loses a lineage path) is
423	// still affected even if the edge is gone in the final graph. Removed datasets
424	// are seeds too, so a downstream that lost its upstream node is counted.
425	func affectedDownstreams(original, final adjacency, newNames, changedNames, removedNames []string) []string {
426		seeds := make(map[string]bool, len(newNames)+len(changedNames)+len(removedNames))
427		for _, name := range newNames {
428			seeds[name] = true
429		}
430		for _, name := range changedNames {
431			seeds[name] = true
432		}
433		for _, name := range removedNames {
434			seeds[name] = true
435		}
436	
437		origChildren := invertAdjacency(original)
438		finalChildren := invertAdjacency(final)
439	
440		seen := make(map[string]bool)
441		queue := make([]string, 0, len(seeds))
442		for seed := range seeds {
443			queue = append(queue, seed)
444		}
445		for len(queue) > 0 {
446			node := queue[0]
447			queue = queue[1:]
448			for _, child := range origChildren[node] {
449				if !seen[child] {
450					seen[child] = true
451					queue = append(queue, child)
452				}
453			}
454			for _, child := range finalChildren[node] {
455				if !seen[child] {
456					seen[child] = true
457					queue = append(queue, child)
458				}
459			}
460		}
461	
462		out := make([]string, 0, len(seen))
463		for name := range seen {
464			if !seeds[name] {
465				out = append(out, name)
466			}
467		}
468		sort.Strings(out)
469		return out
470	}
471	
472	// invertAdjacency maps each dataset to the datasets that depend on it (its
473	// children), with each child list sorted by name.
474	func invertAdjacency(adj adjacency) map[string][]string {
475		children := make(map[string][]string, len(adj))
476		for name, parents := range adj {
477			for _, parent := range parents {
478				children[parent] = append(children[parent], name)
479			}
480		}
481		for name := range children {
482			sort.Strings(children[name])
483		}
484		return children
485	}
486	
487	// adjacencyToDatasets renders the final adjacency as sorted, JSON-ready
488	// records with non-nil upstream lists.
489	func adjacencyToDatasets(adj adjacency) []GraphDataset {
490		names := make([]string, 0, len(adj))
491		for name := range adj {
492			names = append(names, name)
493		}
494		sort.Strings(names)
495		ds := make([]GraphDataset, 0, len(names))
496		for _, name := range names {
497			parents := adj[name]
498			if parents == nil {
499				parents = []string{}
500			}
501			ds = append(ds, GraphDataset{Name: name, Upstreams: parents})
502		}
503		return ds
504	}
505	
506	// stringSliceEqual reports whether a and b contain the same strings in the
507	// same order. Both are expected to be sorted and duplicate-free.
508	func stringSliceEqual(a, b []string) bool {
509		if len(a) != len(b) {
510			return false
511		}
512		for i := range a {
513			if a[i] != b[i] {
514				return false
515			}
516		}
517		return true
518	}
519	
520	// MarshalGraphFile serializes the in-memory graph to the on-disk JSON format.
521	// The graph must satisfy every structure rule a reader enforces; nil nodes,
522	// empty names, names that are not valid UTF-8 (dataset names or direct upstream
523	// references), missing upstreams, and dependency cycles (including a dataset
524	// that lists itself) reject the export with no bytes returned, so a successful
525	// result can always be read back with UnmarshalGraphFile. The check is
526	// read-only: the in-memory graph is never modified.
527	func MarshalGraphFile(graph map[string]*Lineage) ([]byte, error) {
528		adj, err := graphAdjacency(graph)
529		if err != nil {
530			return nil, err
531		}
532		if err := validateAcyclic(adj); err != nil {
533			return nil, err
534		}
535		gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
536		return json.MarshalIndent(gf, "", "  ")
537	}
538	
539	// UnmarshalGraphFile parses the on-disk graph JSON and rebuilds the in-memory
540	// graph (parents and derived children). The graph is checked with the same
541	// structural rules a snapshot enforces (empty names, duplicate datasets,
542	// missing upstreams, and cycles); a structurally invalid graph is rejected so
543	// it cannot be used as the basis for a batch. As in a snapshot, a known field
544	// declared twice within the same object — datasets in the graph object, name
545	// or upstreams in a dataset record — is ambiguous and rejects the whole file,
546	// even when the duplicates carry identical values.
547	func UnmarshalGraphFile(data []byte) (map[string]*Lineage, error) {
548		if err := checkGraphFileDuplicateFields(data); err != nil {
549			return nil, err
550		}
551		// Every name the graph carries must survive decoding exactly as written:
552		// a raw literal with invalid UTF-8 bytes or an unpaired surrogate escape
553		// would be silently rewritten to U+FFFD by json.Unmarshal, and a corrupted
554		// upstream could then resolve to a genuinely different dataset (an edge
555		// written as "源" plus a lone \uD800 would point at the real dataset
556		// "源�"). See name_encoding.go.
557		if err := checkGraphNameEncoding(data); err != nil {
558			return nil, err
559		}
560		var gf GraphFile
561		if err := json.Unmarshal(data, &gf); err != nil {
562			return nil, fmt.Errorf("invalid graph JSON: %w", err)
563		}
564		adj, err := validateGraphStructureFromFile(gf.Datasets)
565		if err != nil {
566			return nil, err
567		}
568		// Rebuild children from the parent edges so the in-memory graph is
569		// consistent regardless of how the file was produced.
570		return lineageFromAdjacency(adj), nil
571	}
572	
573	// UnmarshalPlan parses the plan JSON. The plan structure (empty names,
574	// duplicate declarations) is validated later by computeBatch so that preview
575	// and apply share identical rejection behavior.
576	//
577	// A known field declared twice within the same object — changes or removals
578	// at the top level, name or upstreams inside one change record — is
579	// ambiguous: the reader would silently keep only the last declaration and
580	// drop the earlier adjustment. The whole plan is refused instead, even when
581	// the duplicates carry identical values, one is null, or the surviving value
582	// is a legal empty list. Field names are recognized the same way the decoder
583	// resolves them (after JSON unescaping, with Unicode case folding), so a
584	// second declaration spelled "Changes" or "changes" still collides;
585	// dataset names themselves stay case-sensitive. Unknown fields keep their
586	// ignore-everything behavior and may repeat freely.
587	//
588	// Every name that takes part in the adjustment — each change record's name,
589	// every upstreams entry, and every removals entry — must also survive
590	// decoding exactly as written: a raw string literal carrying bytes that are
591	// not valid UTF-8, or a \u escape forming an unpaired surrogate, would be
592	// silently rewritten to U+FFFD by the decoder, and the corrupted name could
593	// then collide with a genuinely different dataset (a removals entry meant
594	// for no one could delete the dataset really named "�"). The whole plan is
595	// refused instead, naming the field and the zero-based record or array
596	// position, even when the corrupted name would only have matched a dataset
597	// that does not exist. A genuine "�", correctly paired surrogate escapes,
598	// and names that merely look like escapes (a backslash before an ordinary
599	// letter) stay legal; unknown fields and their nested strings are not
600	// checked. The raw scan is shared with the graph readers and lives in
601	// name_encoding.go; this file only supplies the plan document scope.
602	func UnmarshalPlan(data []byte) (Plan, error) {
603		var p Plan
604		if err := checkPlanDuplicateFields(data); err != nil {
605			return p, err
606		}
607		if err := json.Unmarshal(data, &p); err != nil {
608			return p, fmt.Errorf("invalid plan JSON: %w", err)
609		}
610		if err := checkPlanNameEncoding(data); err != nil {
611			return Plan{}, err
612		}
613		return p, nil
614	}
615	
616	// checkGraphFileDuplicateFields applies the shared repeated-known-field rule
617	// (see duplicate_fields.go) to a standalone graph file, supplying the graph
618	// file's own location: datasets may be declared only once in the top-level
619	// graph object, and name and upstreams only once in each dataset record. The
620	// scan is the same checkGraphObject ParseSnapshot runs on the embedded graph,
621	// so preview, apply, and snapshot can never disagree about a graph that
622	// repeats a known field.
623	func checkGraphFileDuplicateFields(data []byte) error {
624		return runFieldScan(data, func(dec *json.Decoder) error {
625			return checkGraphObject(dec, "at the top level of the graph")
626		})
627	}
628	
629	// checkPlanDuplicateFields applies the shared repeated-known-field rule (see
630	// duplicate_fields.go) to a plan, supplying the plan's own field scope and
631	// locations: changes or removals at the top level, and name or upstreams
632	// inside each change record. A change record carries the same fields as a
633	// dataset record, so both use the shared datasetRecordFields scope and a plan
634	// can never be judged differently from the other documents about what counts
635	// as a repeated field.
636	func checkPlanDuplicateFields(data []byte) error {
637		return runFieldScan(data, func(dec *json.Decoder) error {
638			return checkObjectFields(dec, "at the top level of the plan", []knownField{
639				{name: "changes", nested: func(dec *json.Decoder) error {
640					return checkArrayElements(dec, func(dec *json.Decoder, index int) error {
641						return checkObjectFields(dec, fmt.Sprintf("in the change record at index %d of \"changes\"", index), datasetRecordFields)
642					})
643				}},
644				{name: "removals"},
645			})
646		})
647	}
