338	// TestOldSnapshotExportsAfterGraphCorruptsRebuildFails verifies the boundary
339	// around a graph that becomes invalid after a snapshot was taken: the existing
340	// legal snapshot still exports and parses unchanged, while building again from
341	// the corrupt graph fails by the existing rules, returns no usable snapshot,
342	// and mutates neither the graph nor the previously saved snapshot.
343	func TestOldSnapshotExportsAfterGraphCorruptsRebuildFails(t *testing.T) {
344		cases := map[string]struct {
345			corrupt  func(map[string]*Lineage)
346			wantErr  error
347			checkErr func(error) bool
348		}{
349			"missing upstream": {
350				corrupt: func(g map[string]*Lineage) { g["B"].Parents = []string{"ghost"} },
351				wantErr: ErrNotFound,
352			},
353			"cycle introduced": {
354				corrupt: func(g map[string]*Lineage) { g["A"].Parents = []string{"B"} },
355				wantErr: ErrCycle,
356			},
357		}
358		for name, tc := range cases {
359			t.Run(name, func(t *testing.T) {
360				graph := buildGraph(t, P("A"), P("B", "A"), P("C", "B"))
361				old, err := BuildSnapshot(graph)
362				if err != nil {
363					t.Fatalf("initial BuildSnapshot unexpected error: %v", err)
364				}
365				wantID := old.ContentID
366				wantBytes := mustMarshalSnapshot(t, old)
367	
368				tc.corrupt(graph)
369				graphDumpAfterCorruption := dump(graph)
370	
371				bad, err := BuildSnapshot(graph)
372				if !errors.Is(err, tc.wantErr) {
373					t.Fatalf("BuildSnapshot on corrupt graph err = %v, want %v", err, tc.wantErr)
374				}
375				if bad != nil {
376					t.Fatalf("failed build returned a usable snapshot: %#v", bad)
377				}
378	
379				// The failed build changed nothing: the corrupt graph is as the
380				// caller left it and the old snapshot is byte-for-byte intact.
381				if got := dump(graph); got != graphDumpAfterCorruption {
382					t.Errorf("failed build mutated the graph:\n got %s\nwant %s", got, graphDumpAfterCorruption)
383				}
384				if got := old.ContentID; got != wantID {
385					t.Errorf("old snapshot content id = %s, want %s", got, wantID)
386				}
387				if got := mustMarshalSnapshot(t, old); !bytes.Equal(got, wantBytes) {
388					t.Errorf("old snapshot export changed:\n got %s\nwant %s", got, wantBytes)
389				}
390				parsed, err := ParseSnapshot(wantBytes)
391				if err != nil {
392					t.Fatalf("old snapshot no longer parses: %v", err)
393				}
394				if parsed.ContentID != wantID {
395					t.Errorf("parsed old snapshot id = %s, want %s", parsed.ContentID, wantID)
396				}
397			})
398		}
399	}
400	
401	// TestSnapshotPreservesNameCaseAndWhitespace verifies that the frozen records
402	// keep dataset and upstream names verbatim: casing and surrounding spaces
403	// still distinguish datasets, and the distinction survives the full export
404	// and re-read.
405	func TestSnapshotPreservesNameCaseAndWhitespace(t *testing.T) {
406		// "A", "a", and " A " are three different datasets; M derives from the
407		// two space/case-variant roots.
408		graph := buildGraph(t, P("A"), P("a"), P(" A "), P("M", " A ", "a"))
409		snap, err := BuildSnapshot(graph)
410		if err != nil {
411			t.Fatalf("BuildSnapshot unexpected error: %v", err)
412		}
413	
414		// Byte order sorts " A " (0x20) before "A" (0x41) before "M" before "a"
415		// (0x61); the point here is not the exact order but that every spelling
416		// survives as its own record.
417		names := map[string]bool{}
418		for _, ds := range snap.Graph.Datasets {
419			names[ds.Name] = true
420		}
