437			t.Fatalf("name-variant snapshot failed to parse: %v", err)
438		}
439		if parsed.ContentID != snap.ContentID {
440			t.Errorf("parsed content id = %s, want %s", parsed.ContentID, snap.ContentID)
441		}
442		if !reflect.DeepEqual(parsed.Graph, snap.Graph) {
443			t.Errorf("parsed graph differs: %#v\nwant %#v", parsed.Graph, snap.Graph)
444		}
445	
