261		downU := traceReportOf(t, snap, "U")
262	
263		wantSecond := mustMarshalTraceReport(t, second)
264		wantU := mustMarshalTraceReport(t, downU)
265		snapshotBytes := mustMarshalSnapshot(t, snap)
266	
267		// Edit the first report as thoroughly as a caller might: report-level
268		// identifiers, both root fields, every path position, appends into both
269		// paths (including the shared prefix), and a fabricated extra source.
270		first.ContentID = "HACK"
271		first.Dataset = "HACK"
272		first.Sources[0].Root = "HACK"
273		first.Sources[0].Path[0] = "HACK"
274		first.Sources[0].Path[1] = "HACK"
275		first.Sources[0].Path[2] = "HACK"
276		first.Sources[0].Path = append(first.Sources[0].Path, "EXTRA")
277		first.Sources[1].Path = append(first.Sources[1].Path, "EXTRA")
278		first.Sources = append(first.Sources, SourceTrace{Root: "FAKE", Path: []string{"FAKE"}})
279	
280		// The untouched report of the same query is byte-identical to what T
281		// returned.
282		if got := mustMarshalTraceReport(t, second); !bytes.Equal(got, wantSecond) {
283			t.Errorf("second T report changed after editing the first:\n got %s\nwant %s", got, wantSecond)
284		}
285		if !reflect.DeepEqual(second.Sources, wantIndependenceTSources) {
286			t.Errorf("second T sources = %+v, want %+v", second.Sources, wantIndependenceTSources)
287		}
288		if second.Dataset != "T" || second.ContentID != snap.ContentID {
289			t.Errorf("second T metadata = %q %q, want %q %q", second.Dataset, second.ContentID, "T", snap.ContentID)
290		}
291	
292		// The report for the other downstream through the same M is independent as
293		// well.
294		if got := mustMarshalTraceReport(t, downU); !bytes.Equal(got, wantU) {
295			t.Errorf("U report changed after editing T's report:\n got %s\nwant %s", got, wantU)
296		}
297		if !reflect.DeepEqual(downU.Sources, wantIndependenceUSources) {
298			t.Errorf("U sources = %+v, want %+v", downU.Sources, wantIndependenceUSources)
299		}
300	
301		// The snapshot stays frozen.
302		if got := mustMarshalSnapshot(t, snap); !bytes.Equal(got, snapshotBytes) {
303			t.Errorf("snapshot export changed:\n got %s\nwant %s", got, snapshotBytes)
304		}
305		if got := snapshotDatasetsCopy(snap); !reflect.DeepEqual(got, wantIndependenceSnapshotDatasets) {
306			t.Errorf("snapshot datasets changed:\n got %v\nwant %v", got, wantIndependenceSnapshotDatasets)
307		}
308	
309		// Fresh queries still describe the frozen snapshot, not the edited report.
310		freshT := traceReportOf(t, snap, "T")
311		if !reflect.DeepEqual(freshT.Sources, wantIndependenceTSources) {
312			t.Errorf("fresh T sources = %+v, want %+v", freshT.Sources, wantIndependenceTSources)
313		}
314		if freshT.ContentID != snap.ContentID || freshT.Dataset != "T" {
315			t.Errorf("fresh T metadata = %q %q, want %q %q", freshT.ContentID, freshT.Dataset, snap.ContentID, "T")
316		}
317		freshU := traceReportOf(t, snap, "U")
318		if !reflect.DeepEqual(freshU.Sources, wantIndependenceUSources) {
319			t.Errorf("fresh U sources = %+v, want %+v", freshU.Sources, wantIndependenceUSources)
320		}
321		if freshU.ContentID != snap.ContentID || freshU.Dataset != "U" {
322			t.Errorf("fresh U metadata = %q %q, want %q %q", freshU.ContentID, freshU.Dataset, snap.ContentID, "U")
323		}
324	}
