456	// TestTraceIndependentReportStillObeysBusinessRulesWithUnicodeNames verifies on
457	// the independence results themselves that the existing business rules still
458	// hold and that name spellings survive verbatim: Chinese characters, ASCII
459	// case, and surrounding spaces are all kept; each root appears once; the
460	// shortest route wins; equal-length ties are decided element by element from
461	// the query end by UTF-8 byte order; sources are ordered by root name. Editing
462	// the returned names and re-querying returns the original frozen answer.
463	func TestTraceIndependentReportStillObeysBusinessRulesWithUnicodeNames(t *testing.T) {
464		// Q reaches root r in two equal-length relations — via A or via a — and
465		// reaches the two spaced/Chinese roots through the spaced intermediate
466		// " 中间 ". "A" (0x41) beats "a" (0x61) at the first differing position.
467		graphJSON := `{"datasets":[
468			{"name":"Q","upstreams":["A","a"," 中间 "]},
469			{"name":"A","upstreams":["r"]},
470			{"name":"a","upstreams":["r"]},
471			{"name":"r","upstreams":[]},
472			{"name":" 中间 ","upstreams":[" 根 ","根"]},
473			{"name":" 根 ","upstreams":[]},
474			{"name":"根","upstreams":[]}
475		]}`
476		snap := snapshotOf(t, graphJSON)
477	
478		// Roots sort by UTF-8 byte order: the space-prefixed name (0x20) first,
479		// then "r" (0x72), then the Chinese root (0xE6...).
480		want := []SourceTrace{
481			{Root: " 根 ", Path: []string{"Q", " 中间 ", " 根 "}},
482			{Root: "r", Path: []string{"Q", "A", "r"}},
483			{Root: "根", Path: []string{"Q", " 中间 ", "根"}},
484		}
485		report := traceReportOf(t, snap, "Q")
486		if !reflect.DeepEqual(report.Sources, want) {
487			t.Fatalf("Sources = %+v\nwant %+v", report.Sources, want)
488		}
489		if report.ContentID != snap.ContentID || report.Dataset != "Q" {
490			t.Errorf("metadata = %q %q, want %q %q", report.ContentID, report.Dataset, snap.ContentID, "Q")
491		}
492	
493		// Each root appears exactly once.
494		seen := map[string]int{}
495		for _, src := range report.Sources {
496			seen[src.Root]++
497		}
498		for root, count := range seen {
499			if count != 1 {
500				t.Errorf("root %q reported %d times, want exactly once", root, count)
501			}
502		}
503	
504		// The spaced intermediate query keeps every spelling verbatim, and the
505		// spaced root's own query is a single-element path with its spaces intact.
506		mid := traceReportOf(t, snap, " 中间 ")
507		wantMid := []SourceTrace{
508			{Root: " 根 ", Path: []string{" 中间 ", " 根 "}},
509			{Root: "根", Path: []string{" 中间 ", "根"}},
510		}
511		if !reflect.DeepEqual(mid.Sources, wantMid) {
512			t.Errorf("intermediate sources = %+v, want %+v", mid.Sources, wantMid)
513		}
514		spacedRoot := traceReportOf(t, snap, " 根 ")
515		if got := spacedRoot.Sources; !reflect.DeepEqual(got, []SourceTrace{{Root: " 根 ", Path: []string{" 根 "}}}) {
516			t.Errorf("spaced root sources = %+v, want single-element verbatim path", got)
517		}
518	
519		// Edit every name position of every returned path, then re-query: the
520		// frozen answer must come back byte-for-byte, proving the independence copy
521		// preserved the exact spellings.
522		for i := range report.Sources {
523			for j := range report.Sources[i].Path {
524				report.Sources[i].Path[j] = " 改 A "
525			}
526			report.Sources[i].Root = " 改 A "
527			report.Sources[i].Path = append(report.Sources[i].Path, "追加")
528		}
529		for i := range mid.Sources {
530			mid.Sources[i].Path[0] = "HACK"
531		}
