159		// A snapshot whose STRUCTURE is fine but whose stored content id does not
160		// match its graph bytes must be rejected as tampered.
161		tampered := *good
162		tampered.ContentID = good.ContentID + "deadbeef"
163		tb, err := MarshalSnapshot(&tampered)
164		if err != nil {
165			t.Fatalf("marshal tampered: %v", err)
166		}
167		if _, err := ParseSnapshot(tb); !errors.Is(err, ErrInvalidArgument) {
168			t.Fatalf("tampered id err = %v, want ErrInvalidArgument", err)
169		}
