172	// TestParseSnapshotRejectsDuplicateFields: a known field declared twice within
173	// the same object makes the whole snapshot ambiguous and must be rejected,
174	// even when the duplicates carry identical values, the first is null, or the
175	// surviving value would pass every version and content check.
176	func TestParseSnapshotRejectsDuplicateFields(t *testing.T) {
177		graph := `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`
178		id := snapshotOf(t, graph).ContentID
179		doc := func(body string) string {
180			return `{"formatVersion":1,"contentId":"` + id + `","graph":` + body + `}`
181		}
182		// A complete, otherwise valid document; mutations below re-declare one
183		// known field inside it.
184		valid := doc(graph)
185	
186		cases := map[string]struct {
187			data  string
188			field string
189		}{
190			"version 2 then 1": {
191				`{"formatVersion":2,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
192				"formatVersion",
193			},
194			"identical version twice": {
195				`{"formatVersion":1,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
196				"formatVersion",
197			},
198			"contentId twice": {
199				`{"formatVersion":1,"contentId":"` + id + `","contentId":"` + id + `","graph":` + graph + `}`,
200				"contentId",
201			},
202			"null contentId then valid": {
203				`{"formatVersion":1,"contentId":null,"contentId":"` + id + `","graph":` + graph + `}`,
204				"contentId",
205			},
206			"empty graph then real graph": {
207				`{"formatVersion":1,"contentId":"` + id + `","graph":{"datasets":[]},"graph":` + graph + `}`,
208				"graph",
209			},
210			"null graph then real graph": {
211				`{"formatVersion":1,"contentId":"` + id + `","graph":null,"graph":` + graph + `}`,
212				"graph",
213			},
214			"datasets twice": {
215				doc(`{"datasets":[],"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`),
216				"datasets",
217			},
218			"name twice same value": {
219				doc(`{"datasets":[{"name":"A","name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`),
220				"name",
221			},
222			"upstreams twice": {
223				doc(`{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"],"upstreams":["A"]}]}`),
224				"upstreams",
225			},
226			"null upstreams then valid": {
227				doc(`{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":null,"upstreams":["A"]}]}`),
228				"upstreams",
229			},
230			"escaped name key": {
231				doc(`{"datasets":[{"na\u006de":"A","name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`),
232				"name",
233			},
234			"case variant name": {
235				doc(`{"datasets":[{"Name":"A","name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`),
236				"name",
237			},
238			"case variant formatVersion": {
239				`{"FormatVersion":1,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
240				"formatVersion",
241			},
242			"case variant datasets": {
243				doc(`{"Datasets":[],"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`),
244				"datasets",
245			},
246		}
247		for name, tc := range cases {
248			t.Run(name, func(t *testing.T) {
249				_, err := ParseSnapshot([]byte(tc.data))
250				if !errors.Is(err, ErrInvalidArgument) {
251					t.Fatalf("err = %v, want ErrInvalidArgument", err)
252				}
253				if !strings.Contains(err.Error(), `"`+tc.field+`"`) {
254					t.Errorf("err = %q, want it to name field %q", err, tc.field)
255				}
256			})
257		}
258	
259		// The duplicate lives in the second dataset record; the error must locate
260		// it by datasets array index.
261		indexed := doc(`{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"],"upstreams":["A"]}]}`)
262		_, err := ParseSnapshot([]byte(indexed))
263		if err == nil || !strings.Contains(err.Error(), "index 1") {
264			t.Errorf("err = %v, want the datasets index of the offending record", err)
265		}
266	
267		// Sanity: the unmutated document parses and keeps its content id.
268		parsed, err := ParseSnapshot([]byte(valid))
269		if err != nil {
270			t.Fatalf("valid snapshot rejected: %v", err)
271		}
272		if parsed.ContentID != id {
273			t.Errorf("content id = %s, want %s", parsed.ContentID, id)
274		}
275	}
