345	// TestParseSnapshotLargeJSONNumberInUnknownFieldsAccepted: an oversized-but-
346	// legal JSON number carries no lineage semantics, so a snapshot with no
347	// repeated known field must still read successfully even when such numbers
348	// appear directly in unknown fields or nested in their objects and arrays. The
349	// unknown fields (and duplicate keys nested inside them) stay ignored, the
350	// graph's content identifier is unchanged, and genuinely malformed JSON still
351	// fails.
352	func TestParseSnapshotLargeJSONNumberInUnknownFieldsAccepted(t *testing.T) {
353		graph := `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`
354		id := snapshotOf(t, graph).ContentID
355	
356		cases := map[string]string{
357			"big direct value": `{"note":1e400,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
358			"big values nested in unknown fields": `{"formatVersion":1,"contentId":"` + id +
359				`","graph":{"datasets":[{"name":"A","upstreams":[],"note":{"name":1,"name":2,"big":[1e400,{"z":1e999}]}},{"name":"B","upstreams":["A"]}],"meta":[1e400,-1e400]}}`,
360			"repeated unknown field holding big numbers": `{"note":1e400,"note":2e400,"formatVersion":1,"contentId":"` + id + `","graph":` +
361				graph + `,"extra":{"datasets":1e400,"formatVersion":1e400}}`,
362		}
363		for name, data := range cases {
364			t.Run(name, func(t *testing.T) {
365				parsed, err := ParseSnapshot([]byte(data))
366				if err != nil {
367					t.Fatalf("ParseSnapshot rejected a legal document with big numbers: %v", err)
368				}
369				if parsed.ContentID != id {
370					t.Errorf("content id = %s, want %s; unknown fields must not change content identity", parsed.ContentID, id)
371				}
372			})
373		}
374	
375		// A big number does not excuse malformed JSON: the syntax error still has
376		// to surface with a non-zero failure.
377		for name, broken := range map[string]string{
378			"truncated after big number": `{"note":1e400,"formatVersion":`,
379			"malformed number syntax":    `{"note":1e,"formatVersion":1}`,
380		} {
381			t.Run(name, func(t *testing.T) {
382				if _, err := ParseSnapshot([]byte(broken)); err == nil {
383					t.Fatalf("ParseSnapshot accepted malformed JSON %q", broken)
384				}
385			})
386		}
387	}
