572	// A is a root source of B, C depends on B; repointing B at another root X must
573	// report BOTH B and C changing source from A to X.
574	func TestCompareHeadlineRootSourceChange(t *testing.T) {
575		oldSnap := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]},{"name":"C","upstreams":["B"]}]}`)
